# Convert Kanal -> Marla so Area Size / Area Type become consistent (Marla)


if 'Area Size' in model_df.columns and 'Area Type' in model_df.columns:
    # Normalize Area Size numeric and convert Kanal -> Marla (1 Kanal = 20 Marla)
    def _convert_df_area(df):
        df = df.copy()
        if 'Area Type' in df.columns and 'Area Size' in df.columns:
            at = df['Area Type'].astype(str).str.lower().fillna('')
            mask_kanal = at.str.contains('kanal', na=False)
            if mask_kanal.any():
                df.loc[mask_kanal, 'Area Size'] = pd.to_numeric(df.loc[mask_kanal, 'Area Size'], errors='coerce') * 20.0
                df.loc[mask_kanal, 'Area Type'] = 'Marla'
        # Also update free-text 'area' column if present (e.g. "1 Kanal" -> "20 Marla")
        if 'area' in df.columns:
            def _replace_kanal_text(txt):
                if not isinstance(txt, str) or txt.strip() == '':
                    return txt
                m = re.search(r'([0-9]+(?:[.,][0-9]+)?)\s*kanal', txt, flags=re.I)
                if m:
                    num = float(m.group(1).replace(',', '.'))
                    marla = num * 20.0
                    # preserve other text (e.g. "1 Kanal" -> "20 Marla")
                    return re.sub(r'([0-9]+(?:[.,][0-9]+)?)\s*kanal', f'{marla:g} Marla', txt, flags=re.I)
                return txt
            df['area'] = df['area'].astype(str).apply(_replace_kanal_text)
        return df


