# 3) Train-isolated outlier handling helpers (applied after the split)
def compute_outlier_bounds(train_df, cols, multiplier=2.5):
    bounds = {}
    for col in cols:
        try:
            if col not in train_df.columns:
                continue


            series = pd.to_numeric(train_df[col], errors='coerce').dropna()
            if series.empty:
                continue


            q1 = series.quantile(0.25)
            q3 = series.quantile(0.75)
            iqr = q3 - q1
            lower = q1 - multiplier * iqr
            upper = q3 + multiplier * iqr
            bounds[col] = (float(lower), float(upper))
        except Exception as e:
            logger.debug(f'Could not compute bounds for {col}: {e}')
    return bounds


def apply_outlier_bounds(frame, bounds):
    clipped = frame.copy()
    for col, (lower, upper) in bounds.items():
        if col in clipped.columns:
            clipped[col] = pd.to_numeric(clipped[col], errors='coerce').clip(lower, upper)
    return clipped

